//! The signer against the official Python SDK (`hyperliquid-python-sdk`
//! 0.24.0): for each action, built here from this crate's own types, the
//! msgpack bytes, the action hash and the signature must equal what the SDK
//! made with the same test key and nonce (`sdk_vectors.json`, generated by
//! `sign_l1_action`). A mismatch means Hyperliquid would refuse the
//! signature — or read a different action.

use hyperliquid_client::signing::*;
use hyperliquid_client::Network;
use serde_json::Value;

fn order(a: u32, b: bool, s: &str, p: &str, t: OrderTypeWire, r: bool) -> OrderWire {
    OrderWire { a, b, p: p.into(), s: s.into(), r, t, c: None }
}

fn sl(px: &str) -> OrderTypeWire {
    OrderTypeWire::trigger(true, px.into(), "sl")
}

fn action_for(name: &str) -> Vec<u8> {
    let gtc = OrderTypeWire::limit(Tif::Gtc);
    let ioc = OrderTypeWire::limit(Tif::Ioc);
    match name {
        "order_gtc_btc" => rmp_serde::to_vec_named(&OrderAction::new(vec![order(0, true, "0.01", "63768.5", gtc, false)], Grouping::Na)),
        "order_ioc_reduce_gold" => rmp_serde::to_vec_named(&OrderAction::new(vec![order(110003, false, "0.5", "3715.1", ioc, true)], Grouping::Na)),
        "order_trigger_entry_with_tpsl" => rmp_serde::to_vec_named(&OrderAction::new(
            vec![
                order(1, true, "0.2", "1900", sl("1810"), false),
                order(1, false, "0.2", "1700", sl("1750"), true),
                order(1, false, "0.2", "1900", OrderTypeWire::trigger(true, "1900".into(), "tp"), true),
            ],
            Grouping::NormalTpsl,
        )),
        "position_tpsl" => rmp_serde::to_vec_named(&OrderAction::new(vec![order(0, false, "0.01", "56000", sl("62000.5"), true)], Grouping::PositionTpsl)),
        "cancel" => rmp_serde::to_vec_named(&CancelAction::new(vec![CancelWire { a: 0, o: 123456789 }, CancelWire { a: 110003, o: 42 }])),
        "batch_modify" => rmp_serde::to_vec_named(&ModifyAction::new(vec![ModifyWire { oid: 987654321, order: order(0, true, "0.012", "63000", gtc, false) }])),
        "update_leverage_isolated" => rmp_serde::to_vec_named(&LeverageAction::isolated(110003, 20)),
        other => panic!("no action for vector {other}"),
    }
    .unwrap()
}

fn sign_for(name: &str, w: &Wallet, nonce: u64, net: Network) -> Signature {
    let gtc = OrderTypeWire::limit(Tif::Gtc);
    let ioc = OrderTypeWire::limit(Tif::Ioc);
    match name {
        "order_gtc_btc" => sign_l1(w, &OrderAction::new(vec![order(0, true, "0.01", "63768.5", gtc, false)], Grouping::Na), nonce, net),
        "order_ioc_reduce_gold" => sign_l1(w, &OrderAction::new(vec![order(110003, false, "0.5", "3715.1", ioc, true)], Grouping::Na), nonce, net),
        "order_trigger_entry_with_tpsl" => sign_l1(
            w,
            &OrderAction::new(
                vec![
                    order(1, true, "0.2", "1900", sl("1810"), false),
                    order(1, false, "0.2", "1700", sl("1750"), true),
                    order(1, false, "0.2", "1900", OrderTypeWire::trigger(true, "1900".into(), "tp"), true),
                ],
                Grouping::NormalTpsl,
            ),
            nonce,
            net,
        ),
        "position_tpsl" => sign_l1(w, &OrderAction::new(vec![order(0, false, "0.01", "56000", sl("62000.5"), true)], Grouping::PositionTpsl), nonce, net),
        "cancel" => sign_l1(w, &CancelAction::new(vec![CancelWire { a: 0, o: 123456789 }, CancelWire { a: 110003, o: 42 }]), nonce, net),
        "batch_modify" => sign_l1(w, &ModifyAction::new(vec![ModifyWire { oid: 987654321, order: order(0, true, "0.012", "63000", gtc, false) }]), nonce, net),
        "update_leverage_isolated" => sign_l1(w, &LeverageAction::isolated(110003, 20), nonce, net),
        other => panic!("no action for vector {other}"),
    }
    .unwrap()
}

#[test]
fn every_action_signs_exactly_as_the_official_sdk_does() {
    let v: Value = serde_json::from_str(include_str!("sdk_vectors.json")).unwrap();
    let w = Wallet::from_hex(v["key"].as_str().unwrap()).unwrap();
    assert_eq!(w.address(), v["address"].as_str().unwrap().to_lowercase());
    let nonce = v["nonce"].as_u64().unwrap();
    let cases = v["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 14);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let net = if c["mainnet"].as_bool().unwrap() { Network::Mainnet } else { Network::Testnet };
        assert_eq!(hex::encode(action_for(name)), c["msgpack"].as_str().unwrap(), "{name}: msgpack");
        let mut signed_bytes = action_for(name);
        signed_bytes.extend_from_slice(&nonce.to_be_bytes());
        signed_bytes.push(0);
        let hash = keccak(&signed_bytes);
        assert_eq!(hex::encode(hash), c["hash"].as_str().unwrap().trim_start_matches("0x"), "{name}: hash");
        let sig = sign_for(name, &w, nonce, net);
        assert_eq!(sig.r, c["r"].as_str().unwrap(), "{name} {net:?}: r");
        assert_eq!(sig.s, c["s"].as_str().unwrap(), "{name} {net:?}: s");
        assert_eq!(u64::from(sig.v), c["v"].as_u64().unwrap(), "{name} {net:?}: v");
    }
}
